import{c as a,Q as r,j as t,m as i}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Verified Multi-Agent Orchestration: A Plan-Execute-Verify-Replan Framework for Complex Query Resolution","description":"","frontmatter":{"url":"https://arxiv.org/abs/2603.11445","title":"Verified Multi-Agent Orchestration: A Plan-Execute-Verify-Replan Framework for Complex Query Resolution","archived_date":"2026-07-26T00:00:00.000Z","arxiv_id":2603.11445,"authors":["Xing Zhang","Yanwei Cui","Guanghui Wang","Wei Qiu","Ziyuan Li","Fangwei Han","Yajing Huang","Hengzhi Qiu","Bing Zhu","Peiyang He"],"domains":["cs.AI","cs.MA"],"html":"https://arxiv.org/html/2603.11445v1","pdf_path":"pdfs/2603.11445.pdf","published_date":"2026-03-12T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-03-12-vmao-plan-execute-verify-replan-2603-11445.md","filePath":"research/papers/2026-03-12-vmao-plan-execute-verify-replan-2603-11445.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-03-12-vmao-plan-execute-verify-replan-2603-11445.md"};function o(s,e,l,c,u,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="verified-multi-agent-orchestration-a-plan-execute-verify-replan-framework-for-complex-query-resolution" tabindex="-1">Verified Multi-Agent Orchestration: A Plan-Execute-Verify-Replan Framework for Complex Query Resolution <a class="header-anchor" href="#verified-multi-agent-orchestration-a-plan-execute-verify-replan-framework-for-complex-query-resolution" aria-label="Permalink to &quot;Verified Multi-Agent Orchestration: A Plan-Execute-Verify-Replan Framework for Complex Query Resolution&quot;">​</a></h1><p><strong>Authors</strong>: Xing Zhang, Yanwei Cui, Guanghui Wang, Wei Qiu, Ziyuan Li, Fangwei Han, Yajing Huang, Hengzhi Qiu, Bing Zhu, Peiyang He <strong>Published</strong>: March 12, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2603.11445" target="_blank" rel="noreferrer">https://arxiv.org/abs/2603.11445</a> · <a href="https://arxiv.org/html/2603.11445v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2603.11445 <strong>Categories</strong>: cs.AI; cs.MA <strong>PDF</strong>: <a href="https://arxiv.org/abs/2603.11445" target="_blank" rel="noreferrer">research/papers/pdfs/2603.11445.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>We present Verified Multi-Agent Orchestration (VMAO), a framework that coordinates specialized LLM-based agents through a verification-driven iterative loop. Given a complex query, our system decomposes it into a directed acyclic graph (DAG) of sub-questions, executes them through domain-specific agents in parallel, verifies result completeness via LLM-based evaluation, and adaptively replans to address gaps. The key contributions are: (1) dependency-aware parallel execution over a DAG of sub-questions with automatic context propagation, (2) verification-driven adaptive replanning that uses an LLM-based verifier as an orchestration-level coordination signal, and (3) configurable stop conditions that balance answer quality against resource usage.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>五階段迭代框架 <strong>Plan → Execute → Verify → Replan → Synthesize</strong>，把複雜查詢分解為 DAG 子問題並跑到收斂</li><li><strong>DAGExecutor</strong>：依賴感知的批次平行執行（預設 batch k=3），自動把上游結果傳播到下游子問題</li><li><strong>三層 8-agent 架構</strong>（Tier 1 資料蒐集：RAG/Web Search/Financial/Competitor；Tier 2 分析：Analysis/Reasoning/Raw Data；Tier 3 輸出：Document/Visualization），共配置 8 個 MCP server、42 個工具</li><li><strong>ResultVerifier</strong>：LLM 對每個結果評分，輸出 complete/partial/incomplete 狀態與 0–1 completeness 分數，驅動 <strong>AdaptiveReplanner</strong> 決定重試或引入新子問題</li><li>5 種可配置停止條件：完整度閾值（80%）、高信心度（75% 信心＋50% 覆蓋）、邊際收益遞減（&lt;5% 改進）、token 預算（1M）、最大迭代次數（3）</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>25 個專家策劃的市場研究查詢（4 類別：Performance Analysis / Competitive Intelligence / Financial Investigation / Strategic Assessment）</li><li>完整度分數：VMAO 4.2 vs Static Pipeline 3.5 vs Single-Agent 3.1（<strong>+35%</strong> vs 單 agent）</li><li>來源品質分數：VMAO 4.1 vs 3.2 vs 2.6（<strong>+58%</strong> vs 單 agent）</li><li>資源代價：VMAO 平均 <strong>850K tokens</strong>（單 agent 僅 100K，<strong>8.5 倍</strong>），執行時間約 900 秒</li><li>Strategic Assessment 類別改進最大（+53% 完整度）；執行階段佔 token 用量 61%</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>25 題規模小、未報信心區間；LLM judge（Opus 4.5）與執行模型（Sonnet 4.5）同屬 Claude 家族，儘管有人工審查仍可能有共同偏差</li><li>Static Pipeline baseline 未做元件級消融</li><li>LLM 驗證只評「完整度」不評「準確度」，難以偵測細微事實錯誤或幻覺；不當的查詢分解會把錯誤傳播到下游</li><li>全部實驗限單一模型家族（Claude），跨模型家族效果未測試；8.5 倍 token 成本對延遲敏感場景可能不可接受</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>VMAO「LLM-based verifier 作為 orchestration-level coordination signal」直接對照 <code>core.md</code>「判斷 vs 決定」公理：本論文把 verify 的判斷結果餵回 replanner 做路由決定，是判斷/決定分離的具體實作範例。⚠️ verifier 與執行者同模型家族的共同偏差風險，恰是 <code>core.md §PROPOSE 委派</code>（原 <code>graph.md §G2</code>）「產出者不驗收自己產出、可行時優先異模型」規則的實證佐證。</li><li>5 種顯式停止條件（含 token 預算與邊際收益遞減 &lt;5%）與 <code>core.md §APPLY 自主迴圈</code>（原 <code>loop.md §L2</code>） 四重終止並存宣告高度同構，可作為「no-progress 判準」的量化參考點。⚠️ 論文未報告 verifier 本身的可信度校準（同一 state 連跑是否一致），對照 <code>core.md §APPLY 自主迴圈</code> oracle 資格排查仍缺一角。</li></ul>',16)])])}const h=a(n,[["render",o]]);export{g as __pageData,h as default};
